  const [ searchQuery, setSearchQuery ] = useState('');
  const [ activeSuggestion, setActiveSuggestion ] = useState(-1);

  useEffect(() => {
    const debouncedSearch = setTimeout(() => {
      const filteredSuggestions = options.filter((option) => {
        const lowercaseOption = option.toLowerCase();
        const lowercaseSearchQuery = searchQuery.toLowerCase();
        return lowercaseOption.includes(lowercaseSearchQuery);
      });
      setSuggestions(filteredSuggestions);
    }, 300);
    return () => clearTimeout(debouncedSearch);
  }, [searchQuery, options]);

  const handleSearch = (event) => {
    setSearchQuery(event.target.value);
  };

  const handleKeyDown = (event) => {
    switch (event.key) {
      case 'ArrowUp':
        setActiveSuggestion(Math.max(0, --activeSuggestion));
        break;
      case 'ArrowDown':
        setActiveSuggestion(Math.min(suggestions.length - 1, ++activeSuggestion));
        break;
      case 'Enter':
        if (activeSuggestion >= 0) {
          onChange(suggestions[activeSuggestion]);
          setSearchQuery('');
        }
        break;
    }
  };

  const handleClick = (option) => {
    onChange(option);
    setSearchQuery('');
  };

  return (
    <div>
      <input
        type="text"
        value={searchQuery}
        onChange={handleSearch}
        placeholder={placeholder}
        maxLength={maxLength}
        onKeyDown={handleKeyDown}
      />
      {suggestions.map((option, index) => (
        <div
          key={index}
          className={activeSuggestion === index ? 'active-suggestion' : ''}
          onClick={() => handleClick(option)}
        >
          {option}
        </div>
      ))}
    </div>
  );
};

export default Autocomplete;
