#include <iostream>
#include <thread>

namespace ip = boost::interprocess;

int main() {
    // Create a named semaphore
    ip::interprocess_semaphore semaphore(1, 0);

    // Producer process
    for (int i = 0; i < 10; ++i) {
        // Wait for the semaphore to be released
        semaphore.wait();

        // Produce a message
        std::cout << "Produced: " << i << std::endl;

        // Release the semaphore
        semaphore.post();
    }

    // Consumer process
    for (int i = 0; i < 10; ++i) {
        // Wait for the semaphore to be released
        semaphore.wait();

        // Consume a message
        std::cout << "Consumed: " << i << std::endl;

        // Release the semaphore
        semaphore.post();
    }
}
